<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Store\Action\Query;

use Module\Shared\Exception\AppValidationException;
use Module\Store\Action\Dto\StoreDto;
use Module\Store\Action\Query\GetStoreDetailsQry;
use Module\Store\Model\Store;
use Module\Store\Model\StoreRepository;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class GetStoreDetailsQryTest extends IntegrationTestCase
{
    private GetStoreDetailsQry $sut;

    private StoreRepository $storeRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->storeRepository = $this->container->get(StoreRepository::class);

        $this->sut = new GetStoreDetailsQry($this->storeRepository);
        $this->prepareDb();
    }

    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        int $id,
        string $expectedExceptionClass,
        string $expectedExceptionMessage,
        ?StoreDto $expected,
    ): void {
        if ($expectedExceptionClass) {
            $this->expectException($expectedExceptionClass);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $result = $this->sut->handle($id);

        $this->assertEquals($expected, $result);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'store not found' => [
                'id' => 9999,
                'expectedExceptionClass' => AppValidationException::class,
                'expectedExceptionMessage' => 'id: Store not found',
                'expected' => null,
            ],
            'success' => [
                'id' => 10,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expected' => new StoreDto(10, 'EXT-10', 'Test Store', '1 Main St'),
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->storeRepository->saveWithId(Store::factory('EXT-10', 'Test Store', '1 Main St', 10));
        $this->storeRepository->flush();
    }
}
